 p=pathlib.Path('/tmp/3696-rail-'+name)
 r['binaries'][name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
for pair in range(1,10):
 row={'pair':pair,'observations':[]}
 for name in (['before','after'] if pair%2 else ['after','before']):
  cmd=['/tmp/3696-rail-'+name,'--nocapture']
